export const LESSONS = WORLDS.flatMap(w => DATA[w.year].map((d,i) => ({
 id:`Y${w.year}-${String(i+1).padStart(2,'0')}`,year:w.year,number:i+1,
 title:d[0],topic:d[1],teach:d[2],why:d[9],
 questions:[{prompt:d[3],options:d[4].split('|'),answer:d[5]}, {prompt:d[6],options:d[7].split('|'),answer:d[8]}]
})));
export function getLesson(id){ return LESSONS.find(l=>l.id===id); }
